        if rewriter:
            return rewriter(typ)

        # NOTE: Missing the isinstance(typ, TypeVar) check here!
        # This is what would cause the issue

        return self.generic_rewrite(typ)

    @abstractmethod
    def generic_rewrite(self, typ): ...

# Create a concrete implementation
